<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Supplier extends Model { protected $fillable=['name','code','email','phone','address','tax_id','is_active']; protected $casts=['is_active'=>'boolean']; public function purchases(){return $this->hasMany(Purchase::class);} public function returns(){return $this->hasMany(PurchaseReturn::class);} }
